// Capture agent service — WebSocket server on 127.0.0.1:8766.
//
// The side panel connects here while a capture is pending, sends an `ask`
// (capture tree + question), streams the agent's reasoning back, and on settle
// receives { sessionId, sessionFile, model, cost } so it can stash an `agent`
// envelope on the pending capture before Save.
//
// Protocol (JSON messages):
//   panel → service: { type:"ask", captureId, tree, messages?, prompt }
//                    { type:"follow_up", captureId, prompt }
//                    { type:"abort", captureId }
//   service → panel: { type:"ready" }
//                    { type:"delta", captureId, text }
//                    { type:"tool", captureId, tool, arg }
//                    { type:"settled", captureId, sessionId, sessionFile, model, cost }
//                    { type:"error", captureId, message }
//
// Env:
//   AGENT_PORT        WebSocket port (default 8766)
//   AGENT_DATA_DIR    evidence root (default ../server/data under this repo)
//   AGENT_MOCK=1      stub mode: returns synthetic deltas + a settled event
//                     without hitting OpenRouter (used for tests/smoke).
//   OPENROUTER_API_KEY  required in real mode; never ships in the browser.

import http from "node:http";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { WebSocketServer, WebSocket } from "ws";

import { CaptureAgent } from "./agent.js";
import { makeSystemPrompt } from "./agent.js";
import { costOfMessages, currentModelOf, newSessionId, persistSession } from "./persist.js";

const ROOT = path.dirname(fileURLToPath(import.meta.url));
export const DEFAULT_DATA_DIR = path.resolve(ROOT, "..", "server", "data");
export const DEFAULT_PORT = 8766;

function dataDir() {
  return process.env.AGENT_DATA_DIR ? path.resolve(process.env.AGENT_DATA_DIR) : DEFAULT_DATA_DIR;
}

const IS_MOCK = process.env.AGENT_MOCK === "1";

// ---- messaging helpers ------------------------------------------------------

function send(socket, obj) {
  if (socket && socket.readyState === WebSocket.OPEN) {
    socket.send(JSON.stringify(obj));
  }
}

// A short (safe) transcript of prior turns, used to carry context when a fresh
// session is created (e.g. after a panel reconnect) via the `messages` field.
function serializeMessages(messages) {
  if (!Array.isArray(messages) || messages.length === 0) return "";
  const take = messages.slice(-40);
  const parts = [];
  for (const m of take) {
    const role = (m && m.role) || "";
    let content = m && m.content;
    if (Array.isArray(content)) {
      content = content
        .filter((c) => c && c.type === "text")
        .map((c) => c.text)
        .join(" ");
    }
    if (typeof content === "string" && content.trim()) {
      parts.push(`${role === "assistant" ? "Assistant" : role === "user" ? "User" : role}: ${content.trim()}`);
    }
  }
  return parts.length ? `\n\nPrior conversation so far:\n${parts.join("\n")}` : "";
}

// ---- mock inference (AGENT_MOCK=1) -----------------------------------------

// A tiny "assistant" that streams a deterministic answer and settles, so the
// service + panel protocol is verifiable without an OpenRouter key.
function buildMockAnswer(prompt, tree) {
  const links = [];
  const walk = (n) => {
    for (const l of n.links || []) links.push(l);
    for (const c of n.children || []) walk(c);
  };
  walk(tree || {});
  const urlLine = links.length > 0 ? `\n\nRelevant urls in the capture: ${links[0]}` : "";
  const lines = [
    "This is a stubbed agent answer (AGENT_MOCK=1; no OpenRouter call was made).\n",
    `Your question: "${prompt}".`,
    `The capture contains ${(tree && tree.tweet_text) ? "tweet text" : "a tweet"}${links.length ? ` and ${links.length} link(s)` : ""}.`,
    urlLine,
    "\nA real run would reason over the capture and its urls with the fetch_url tool.",
  ];
  return lines.join("\n");
}

class MockHandle {
  constructor({ captureId, socket, dataDir, model }) {
    this.captureId = captureId;
    this.socket = socket;
    this.dataDir = dataDir;
    this.model = model;
    this.turns = [];
    this.sessionId = newSessionId();
    this.timers = [];
  }
  run(msg) {
    const { prompt, tree } = msg;
    const answer = buildMockAnswer(prompt, tree);
    this.turns.push({ role: "user", content: prompt });
    const chunks = answer.match(/.{1,40}/gs) || [];
    chunks.forEach((chunk, i) => {
      this.timers.push(
        setTimeout(() => {
          send(this.socket, { type: "delta", captureId: this.captureId, text: chunk });
        }, 30 * (i + 1))
      );
    });
    const settledAt = 60 + 30 * chunks.length;
    this.timers.push(
      setTimeout(() => {
        this.turns.push({ role: "assistant", content: answer });
        const { sessionId, sessionFile } = persistSession(
          this.dataDir,
          this.sessionId,
          this.turns.slice()
        );
        send(this.socket, {
          type: "settled",
          captureId: this.captureId,
          sessionId,
          sessionFile,
          model: this.model,
          cost: 0,
        });
      }, settledAt)
    );
  }
  abort() {
    for (const t of this.timers) clearTimeout(t);
    this.timers = [];
  }
}

// ---- main service ----------------------------------------------------------

class AgentService {
  constructor(options = {}) {
    this.dataDir = options.dataDir || dataDir();
    this.cwd = options.cwd || process.cwd();
    this.handles = new Map(); // captureId -> { agent|mock, socket }
  }

  handleFor(captureId) {
    return this.handles.get(captureId);
  }

  async ask(socket, msg) {
    const { captureId, tree, messages, prompt } = msg;
    let handle = this.handles.get(captureId);

    if (handle && handle.agent && handle.agent.isStreaming) {
      send(socket, { type: "error", captureId, message: "Agent is still answering the previous question. Wait for it to finish." });
      return;
    }

    if (!handle || handle.socket !== socket || (handle.mock === false && !handle.agent)) {
      // Fresh handler for this capture (or a reconnect on a new socket).
      if (handle) this.dispose(false);
      handle = this.createHandle(socket, captureId);
    }

    const question = prompt && prompt.trim() ? prompt.trim() : "Analyse this capture.";
    const prior = serializeMessages(messages || []);

    if (handle.mock) {
      handle.mock.run({ prompt: question, tree: tree || {} });
      return;
    }

    try {
      const agent = handle.agent;
      if (!agent.session) await agent.start();
      handle.socket = socket;
      agent.setHandlers({
        onDelta: (text) => send(socket, { type: "delta", captureId, text }),
        onTool: ({ tool, arg }) => send(socket, { type: "tool", captureId, tool, arg }),
        onSettled: (messagesList) => {
          const { sessionId, sessionFile } = persistSession(this.dataDir, handle.sessionId, messagesList);
          const model = String(agent.model && agent.model.id || (currentModelOf(messagesList) || "unknown"));
          const cost = costOfMessages(messagesList);
          send(socket, {
            type: "settled",
            captureId,
            sessionId,
            sessionFile,
            model,
            cost,
          });
        },
      });
      await agent.ask(tree || {}, question + prior);
    } catch (e) {
      send(socket, { type: "error", captureId, message: `Agent unavailable: ${e && e.message ? e.message : e}` });
      this.dispose(captureId);
    }
  }

  async followUp(socket, msg) {
    const { captureId, prompt } = msg;
    const handle = this.handles.get(captureId);
    if (!handle) {
      send(socket, { type: "error", captureId, message: "No active conversation for this capture. Start with an ask." });
      return;
    }
    if (handle.mock) {
      handle.mock.run({ prompt: prompt || "Continue.", tree: {} });
      return;
    }
    const agent = handle.agent;
    if (agent.isStreaming) {
      send(socket, { type: "error", captureId, message: "Agent is still answering. Wait for it to finish." });
      return;
    }
    try {
      await agent.followUp(prompt || "Continue.");
    } catch (e) {
      send(socket, { type: "error", captureId, message: `Agent unavailable: ${e && e.message ? e.message : e}` });
    }
  }

  async abort(msg) {
    const { captureId } = msg;
    const handle = this.handles.get(captureId);
    if (!handle) return;
    if (handle.mock) {
      handle.mock.abort();
      return;
    }
    try {
      if (handle.agent) await handle.agent.abort();
    } catch {
      /* best-effort */
    }
  }

  createHandle(socket, captureId) {
    const handle = { captureId, socket };
    if (process.env.AGENT_MOCK === "1") {
      handle.mock = new MockHandle({
        captureId,
        socket,
        dataDir: this.dataDir,
        model: process.env.AGENT_MODEL || "deepseek/deepseek-v4-flash",
      });
      handle.sessionId = handle.mock.sessionId;
      this.handles.set(captureId, handle);
      return handle;
    }
    handle.agent = new CaptureAgent({ cwd: this.cwd });
    handle.sessionId = newSessionId();
    this.handles.set(captureId, handle);
    return handle;
  }

  dispose(captureId) {
    const handle = this.handles.get(captureId);
    if (!handle) return;
    if (handle.agent) handle.agent.dispose();
    if (handle.mock) handle.mock.abort();
    this.handles.delete(captureId);
  }

  disposeForSocket(socket) {
    for (const [id, handle] of this.handles) {
      if (handle.socket === socket) {
        const hadAgent = !!handle.agent;
        if (hadAgent) handle.agent.dispose();
        if (handle.mock) handle.mock.abort();
        this.handles.delete(id);
      }
    }
  }
}

function onMessage(service, ws, raw) {
  let msg;
  try {
    msg = JSON.parse(raw.toString());
  } catch {
    send(ws, { type: "error", captureId: null, message: "Invalid JSON message" });
    return;
  }
  if (!msg || typeof msg.type !== "string") {
    send(ws, { type: "error", captureId: null, message: "Message must have a type" });
    return;
  }
  const { type, captureId } = msg;
  switch (type) {
    case "ask":
      service.ask(ws, msg).catch((e) =>
        send(ws, { type: "error", captureId, message: `ask failed: ${e && e.message ? e.message : e}` })
      );
      break;
    case "follow_up":
      service.followUp(ws, msg).catch((e) =>
        send(ws, { type: "error", captureId, message: `follow_up failed: ${e && e.message ? e.message : e}` })
      );
      break;
    case "abort":
      service.abort(msg).catch(() => {});
      break;
    default:
      send(ws, { type: "error", captureId, message: `Unknown message type: ${type}` });
  }
}

export function startServer(options = {}) {
  const port = options.port || Number(process.env.AGENT_PORT) || DEFAULT_PORT;
  const service = new AgentService(options);

  const httpServer = http.createServer((_req, res) => {
    res.writeHead(200, { "Content-Type": "text/plain" });
    res.end("capture agent service");
  });

  const wss = new WebSocketServer({ server: httpServer, path: options.path || "/" });

  wss.on("connection", (ws) => {
    send(ws, { type: "ready" });
    ws.on("message", (raw) => onMessage(service, ws, raw));
    ws.on("close", () => service.disposeForSocket(ws));
    ws.on("error", () => service.disposeForSocket(ws));
  });

  httpServer.listen(port, "127.0.0.1", () => {
    console.log(`>> capture agent service on ws://127.0.0.1:${port} (${IS_MOCK ? "MOCK mode" : "real mode"})`);
    console.log(`>> evidence dir: ${service.dataDir}`);
    if (!IS_MOCK && !process.env.OPENROUTER_API_KEY) {
      console.log(">> WARNING: OPENROUTER_API_KEY not set — asks will report 'agent unavailable'.");
    }
  });

  return { httpServer, wss, service };
}

// Allow a direct `node server.js` start (and keep the module importable for tests).
if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
  startServer();
}

// Side panel logic for Capture.
// Renders the in-progress capture as a live view: the root tweet plus any
// curated comments nested in an indented tree. Re-renders live when the
// content script adds/removes comments (via background broadcast). On Save it
// POSTs the whole recursive tree to the local server.

(() => {
  "use strict";

  const statusEl = document.getElementById("status");
  const contentEl = document.getElementById("content");
  const authorEl = document.getElementById("author");
  const urlEl = document.getElementById("tweet-url");
  const scrapeWarnEl = document.getElementById("scrape-warning");
  const textEl = document.getElementById("tweet-text");
  const linksEl = document.getElementById("links");
  const notesEl = document.getElementById("notes");
  const contextFieldset = document.getElementById("context-fieldset");
  const contextLegend = document.getElementById("context-legend");
  const contextTree = document.getElementById("context-tree");
  const saveBtn = document.getElementById("save");

  // Ask panel (agent)
  const agentFieldset = document.getElementById("agent-fieldset");
  const agentThread = document.getElementById("agent-thread");
  const agentStatus = document.getElementById("agent-status");
  const agentInput = document.getElementById("agent-input");
  const agentAskBtn = document.getElementById("agent-ask");
  const agentAbortBtn = document.getElementById("agent-abort");
  const agentUnavailable = document.getElementById("agent-unavailable");

  let agentUrl = "ws://127.0.0.1:8766";
  let agentBusy = false;
  let agentEnvelope = null; // stashed when the agent settles (attached on Save)
  let agentEverAvail = false;
  let agentPending = null; // { tree, prompt } waiting for a connection
  let agentMessages = []; // { role, content } transcript for reconnection context
  let agentClient = null;

  let serverUrl = "http://127.0.0.1:8765/api/capture";
  let current = null; // the root node of the in-progress capture (has children[])

  function setStatus(msg, kind) {
    statusEl.textContent = "";
    statusEl.className = "status " + (kind || "pending");
    statusEl.innerHTML = msg;
  }

  function clearStatus() {
    statusEl.textContent = "";
    statusEl.className = "";
  }

  function renderLinks(list) {
    linksEl.innerHTML = "";
    const arr = Array.isArray(list) ? list : [];
    if (arr.length === 0) {
      const li = document.createElement("li");
      li.className = "empty";
      li.textContent = "No links found.";
      linksEl.appendChild(li);
      return;
    }
    for (const link of arr) {
      const li = document.createElement("li");
      const cb = document.createElement("input");
      cb.type = "checkbox";
      cb.value = link;
      cb.checked = true;
      const label = document.createElement("label");
      label.textContent = link;
      li.appendChild(cb);
      li.appendChild(label);
      linksEl.appendChild(li);
    }
  }

  // Build one comment node row, indented by depth. Comment links are shown
  // plainly (captured automatically; no per-node toggles in v1).
  function nodeEl(node, depth) {
    const div = document.createElement("div");
    div.className = "cnode";
    div.style.paddingLeft = 6 + depth * 16 + "px";

    if (node.author) {
      const a = document.createElement("div");
      a.className = "c-author";
      a.textContent = node.author;
      div.appendChild(a);
    }
    const t = document.createElement("div");
    t.className = "c-text";
    t.textContent = node.tweet_text || "(no text scraped)";
    div.appendChild(t);
    if (node.tweet_url) {
      const u = document.createElement("span");
      u.className = "c-url";
      u.textContent = node.tweet_url;
      div.appendChild(u);
    }
    if (Array.isArray(node.links) && node.links.length) {
      const ul = document.createElement("ul");
      for (const link of node.links) {
        const li = document.createElement("li");
        li.textContent = link;
        ul.appendChild(li);
      }
      div.appendChild(ul);
    }
    return div;
  }

  function renderChildren(parentNode, depth, container) {
    for (const child of parentNode.children || []) {
      container.appendChild(nodeEl(child, depth));
      renderChildren(child, depth + 1, container);
    }
  }

  // Re-render the Context (comments tree) section only — called on live
  // updates so notes/text edits in the panel aren't clobbered.
  function renderContext() {
    const kids = (current && current.children) || [];
    contextFieldset.style.display = kids.length ? "block" : "none";
    contextLegend.textContent = "Context (" + kids.length + ")";
    contextTree.innerHTML = "";
    if (kids.length) renderChildren(current, 1, contextTree);
  }

  function renderRoot() {
    const node = current || {};
    authorEl.textContent = node.author || "Unknown author";
    urlEl.textContent = node.tweet_url || "";
    textEl.value = node.tweet_text || "";
    if (!node.tweet_text && !node.tweet_url) {
      scrapeWarnEl.style.display = "block";
    } else {
      scrapeWarnEl.style.display = "none";
    }
    renderLinks(node.links || []);
  }

  function render(data) {
    current = data || { tweet_url: "", author: "", tweet_text: "", links: [], parent_url: null, notes: "", children: [] };
    renderRoot();
    renderContext();
    notesEl.value = current.notes || "";
    contentEl.style.display = "block";
    clearStatus();
    resetAgentForNewCapture();
  }

  // Deep-clone current into a tree, apply panel edits (root text, notes,
  // checked root links), and return it for submission.
  function collectArtefact() {
    const tree = JSON.parse(JSON.stringify(current || {}));
    tree.tweet_text = textEl.value.trim();
    tree.notes = notesEl.value.trim();
    const checkedLinks = [];
    for (const li of linksEl.querySelectorAll("li")) {
      const cb = li.querySelector('input[type="checkbox"]');
      if (cb && cb.checked && cb.value) checkedLinks.push(cb.value);
    }
    tree.links = checkedLinks;
    return tree;
  }

  async function submit() {
    if (!(current && current.tweet_url)) {
      setStatus("Nothing to save — no tweet URL.", "error");
      return;
    }
    const artefact = collectArtefact();
    if (agentEnvelope) artefact.agent = agentEnvelope; // link the saved evidence
    saveBtn.disabled = true;
    setStatus("Saving…", "pending");
    try {
      const resp = await fetch(serverUrl, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(artefact),
      });
      if (!resp.ok) throw new Error("HTTP " + resp.status);
      const body = await resp.json();
      setStatus(
        "Saved ✓ " + (body.captured_at ? "at " + body.captured_at : ""),
        "ok"
      );
      chrome.runtime.sendMessage({ type: "clear-pending-capture" });
      saveBtn.disabled = false;
    } catch (e) {
      setStatus(
        "<strong>Server offline</strong> — restart and try again. Your data is still here.",
        "error"
      );
      saveBtn.disabled = false;
    }
  }

  saveBtn.addEventListener("click", submit);

  // ------------------------------------------------------------------------
  // Agent (Ask) — stories 1-5
  // ------------------------------------------------------------------------

  function setAgentStatus(msg, kind) {
    if (!msg) {
      agentStatus.style.display = "none";
      agentStatus.className = "status";
      agentStatus.textContent = "";
      return;
    }
    agentStatus.style.display = "block";
    agentStatus.className = "status " + (kind || "pending");
    agentStatus.textContent = msg;
  }

  function showAgentUnavailable() {
    agentUnavailable.style.display = "block";
    agentFieldset.style.opacity = "0.75";
  }

  function hideAgentUnavailable() {
    agentUnavailable.style.display = "none";
    agentFieldset.style.opacity = "";
  }

  function addAgentBubble(cls, text) {
    const div = document.createElement("div");
    div.className = "agent-msg " + cls;
    div.textContent = text || "";
    agentThread.appendChild(div);
    return div;
  }

  function updateAgentControls() {
    agentAskBtn.disabled = agentBusy || !!(current && current.tweet_url) === false;
    agentAbortBtn.style.display = agentBusy ? "inline-block" : "none";
    agentAskBtn.style.display = agentBusy ? "none" : "inline-block";
  }

  function captureId() {
    return current && current.tweet_url ? "capture:" + current.tweet_url : "capture:active";
  }

  function appendDeliveredText(text) {
    if (!currentAssistantBubble) currentAssistantBubble = addAgentBubble("assistant", "");
    currentAssistantBubble.textContent += text;
    currentAssistantText += text;
    agentThread.scrollTop = agentThread.scrollHeight;
  }

  function flushPendingIfConnected() {
    if (agentPending && agentClient && agentClientWasOpen()) {
      agentClient.ask(agentPending.captureId, agentPending.tree, agentPending.prompt, agentPending.messages);
      agentPending = null;
    }
  }

  function agentClientWasOpen() {
    return agentClient && agentClient.ws && agentClient.ws.readyState === WebSocket.OPEN;
  }

  function initAgentClient() {
    if (agentClient) return;
    agentClient = new AgentClient({
      url: agentUrl,
      handlers: {
        onReady: () => {
          agentEverAvail = true;
          hideAgentUnavailable();
          setAgentStatus("Connected.", "ok");
          setTimeout(() => setAgentStatus(null), 1200);
          flushPendingIfConnected();
        },
        onDelta: (msg) => {
          if (msg.captureId !== captureId()) return;
          appendDeliveredText(msg.text);
        },
        onTool: (msg) => {
          if (msg.captureId !== captureId()) return;
          addAgentBubble("tool", "⚙ fetched " + (msg.arg || msg.tool));
        },
        onSettled: (msg) => {
          if (msg.captureId !== captureId()) return;
          // finalize assistant bubble, stash the envelope for Save
          if (!currentAssistantBubble) currentAssistantBubble = addAgentBubble("assistant", "");
          if (msg.model) {
            const meta = document.createElement("div");
            meta.className = "muted";
            meta.style.cssText = "margin-top:4px;font-size:11px;";
            meta.textContent = "model " + msg.model + (typeof msg.cost === "number" ? " · $" + msg.cost.toFixed(5) : "");
            currentAssistantBubble.appendChild(meta);
          }
          currentAssistantBubble = null;
          agentEnvelope = {
            sessionId: msg.sessionId,
            sessionFile: msg.sessionFile,
            prompt: lastAgentPrompt || "",
            model: msg.model || "",
            capturedAt: new Date().toISOString(),
            cost: typeof msg.cost === "number" ? msg.cost : undefined,
          };
          agentMessages.push({ role: "assistant", content: currentAssistantText });
          currentAssistantText = "";
          agentBusy = false;
          updateAgentControls();
          setAgentStatus("Answer saved with this capture.", "ok");
          setTimeout(() => setAgentStatus(null), 1500);
        },
        onError: (msg) => {
          agentBusy = false;
          updateAgentControls();
          if (msg && /unreachable|unavailable/i.test(msg.message || "")) {
            showAgentUnavailable();
            setAgentStatus("Agent unavailable. You can still save.", "error");
          } else {
            setAgentStatus("Agent error: " + ((msg && msg.message) || "unknown"), "error");
          }
        },
        onDown: (msg) => {
          // service is not up yet — show the unavailable state, keep retrying
          showAgentUnavailable();
          setAgentStatus("Agent unavailable. You can still save.", "error");
        },
      },
    });
    agentClient.connect();
  }

  let currentAssistantBubble = null;
  let currentAssistantText = "";
  let lastAgentPrompt = "";

  function askAgent() {
    if (!(current && current.tweet_url)) {
      setStatus("Nothing to ask about — no tweet URL.", "error");
      return;
    }
    const prompt = agentInput.value.trim();
    if (!prompt) return;
    if (agentBusy) return;

    const tree = collectArtefact();
    lastAgentPrompt = prompt;
    addAgentBubble("user", prompt);
    agentMessages.push({ role: "user", content: prompt });
    agentInput.value = "";
    currentAssistantBubble = null;
    currentAssistantText = "";
    agentBusy = true;
    updateAgentControls();
    hideAgentUnavailable();

    if (agentClientWasOpen()) {
      agentClient.ask(captureId(), tree, prompt, []);
    } else {
      agentPending = { captureId: captureId(), tree, prompt, messages: agentMessages.slice() };
      setAgentStatus("Connecting to agent service…", "pending");
      initAgentClient();
    }
  }

  function followUpAgent() {
    if (agentBusy) return;
    const prompt = agentInput.value.trim();
    if (!prompt) return;
    if (!agentEverAvail) {
      askAgent();
      return;
    }
    lastAgentPrompt = prompt;
    addAgentBubble("user", prompt);
    agentMessages.push({ role: "user", content: prompt });
    agentInput.value = "";
    currentAssistantBubble = null;
    currentAssistantText = "";
    agentBusy = true;
    updateAgentControls();
    if (agentClientWasOpen()) {
      agentClient.followUp(captureId(), prompt);
    } else {
      agentPending = { captureId: captureId(), tree: collectArtefact(), prompt, messages: agentMessages.slice() };
