// Real (pi SDK) agent runner for the capture agent service.
//
// Creates an in-memory AgentSession with exactly one custom tool (fetch_url),
// no coding tools (Decision 03), reasons over the pending capture, streams
// text deltas / tool activity, and on settle hands the full message list back
// so the service can persist it as evidence.

import {
  createAgentSession,
  createExtensionRuntime,
  SessionManager,
  SettingsManager,
} from "@earendil-works/pi-coding-agent";
import { createModelStack, resolveModel } from "./models.mjs";
import { fetchUrlTool } from "./tools/fetch_url.js";
import { serializeTree } from "./serialize.js";

export function makeSystemPrompt() {
  return `You are a research assistant embedded in the Capture instrument. You help the user think about a captured X/Twitter post and the content it links to.

Rules:
- Reason only over the pending capture and the urls inside it.
- When a url in the capture is relevant to the user's question, fetch and read it with the fetch_url tool. You decide which urls matter.
- Use the tool as part of your reasoning, then answer the user's question plainly.
- Be concise and specific. Cite what you actually read; if content is unavailable, say so.
- Never invent, edit, or fabricate content.`;
}

// A fully controlled resource loader: no project/global extensions, skills,
// prompt templates, themes, or context files leak in. Only fetch_url is
// available to the model.
function minimalResourceLoader() {
  return {
    getExtensions: () => ({ extensions: [], errors: [], runtime: createExtensionRuntime() }),
    getSkills: () => ({ skills: [], diagnostics: [] }),
    getPrompts: () => ({ prompts: [], diagnostics: [] }),
    getThemes: () => ({ themes: [], diagnostics: [] }),
    getAgentsFiles: () => ({ agentsFiles: [] }),
    getSystemPrompt: () => makeSystemPrompt(),
    getAppendSystemPrompt: () => [],
    extendResources: () => {},
    reload: async () => {},
  };
}

export class CaptureAgent {
  constructor({ cwd }) {
    this.cwd = cwd || process.cwd();
    this.session = null;
    this.model = null;
    this.handlers = {};
    this.unsub = null;
  }

  get isStreaming() {
    return !!(this.session && this.session.isStreaming);
  }

  async start() {
    const { authStorage, modelRegistry } = createModelStack();
    const model = resolveModel(modelRegistry); // throws if the model is unavailable
    const settingsManager = SettingsManager.inMemory({ compaction: { enabled: false } });
    const { session } = await createAgentSession({
      cwd: this.cwd,
      model,
      thinkingLevel: "medium",
      authStorage,
      modelRegistry,
      settingsManager,
      resourceLoader: minimalResourceLoader(),
      tools: ["fetch_url"],
      customTools: [fetchUrlTool],
      sessionManager: SessionManager.inMemory(this.cwd),
    });
    this.session = session;
    this.model = model;
    this.handlers = {};
    this.unsub = session.subscribe((event) => this._onEvent(event));
    return { model };
  }

  setHandlers(handlers) {
    this.handlers = handlers || {};
  }

  _onEvent(event) {
    if (event.type === "message_update" && event.assistantMessageEvent.type === "text_delta") {
      if (this.handlers.onDelta) this.handlers.onDelta(event.assistantMessageEvent.delta);
    } else if (event.type === "tool_execution_start") {
      if (this.handlers.onTool) {
        this.handlers.onTool({ tool: event.toolName, arg: event.args && event.args.url });
      }
    } else if (event.type === "agent_end") {
      if (this.handlers.onSettled) this.handlers.onSettled(event.messages || []);
    } else if (event.type === "message_end" && this.handlers.onMessageEnd) {
      // reserved
    }
  }

  // First turn: inject the serialized tree (context) then the user's question.
  async ask(tree, prompt) {
    const context = serializeTree(tree || {});
    const userText = prompt && prompt.trim() ? prompt.trim() : "Analyse this capture.";
    await this.session.prompt(`${context}\n\nQuestion: ${userText}`);
  }

  // Follow-up in the same conversation; the session retains capture context.
  async followUp(prompt) {
    await this.session.followUp(prompt && prompt.trim() ? prompt.trim() : "Continue.");
  }

  async abort() {
    if (this.session) await this.session.abort();
  }

  dispose() {
    if (this.unsub) this.unsub();
    if (this.session) this.session.dispose();
    this.session = null;
    this.unsub = null;
  }
}

