// Thin WebSocket client for the capture agent service (ws://127.0.0.1:8766).
//
// Connects with reconnect/backoff, sends { ask | follow_up | abort }, and
// emits the incoming protocol events (delta/tool/settled/error/ready) to
// registered handlers. Kept deliberately small and dependency-free (no
// framework) because it runs inside the MV3 side panel.

class AgentClient {
  /**
   * @param {object} opts
   * @param {string} [opts.url]   ws url (default ws://127.0.0.1:8766)
   * @param {object} [opts.handlers] { onOpen, onDelta, onTool, onSettled, onError, onReady }
   */
  constructor(opts = {}) {
    this.url = opts.url || "ws://127.0.0.1:8766";
    this.handlers = opts.handlers || {};
    this.ws = null;
    this.attempt = 0;
    this.everConnected = false;
    this.maxAttempts = opts.maxAttempts || 8;
    this.baseDelay = opts.baseDelay || 500; // ms
    this.reconnectTimer = null;
    this.manualClose = false;
  }

  connect() {
    this.manualClose = false;
    this._open();
  }

  _open() {
    let ws;
    try {
      ws = new WebSocket(this.url);
    } catch (e) {
      this._scheduleReconnect();
      return;
    }
    this.ws = ws;

    ws.onopen = () => {
      this.attempt = 0;
      this.everConnected = true;
      if (this.handlers.onOpen) this.handlers.onOpen();
    };

    ws.onmessage = (event) => {
      let msg;
      try {
        msg = JSON.parse(event.data);
      } catch (e) {
        return;
      }
      this._dispatch(msg);
    };

    ws.onerror = () => {
      // onerror is followed by onclose; let onclose handle reconnect.
    };

    ws.onclose = () => {
      this.ws = null;
      if (this.manualClose) return;
      if (!this.everConnected && this.handlers.onDown) {
        // never managed to connect — surface "service down" right away
        this.handlers.onDown({ type: "error", message: "agent service unreachable" });
      }
      this._scheduleReconnect();
    };
  }

  _scheduleReconnect() {
    if (this.attempt >= this.maxAttempts) {
      if (this.handlers.onError) {
        this.handlers.onError({ type: "error", message: "agent service unreachable" });
      }
      return;
    }
    const delay = this.baseDelay * Math.pow(2, this.attempt);
    this.attempt += 1;
    this.reconnectTimer = setTimeout(() => this._open(), delay);
  }

  _dispatch(msg) {
    switch (msg.type) {
      case "ready":
        if (this.handlers.onReady) this.handlers.onReady();
        break;
      case "delta":
        if (this.handlers.onDelta) this.handlers.onDelta(msg);
        break;
      case "tool":
        if (this.handlers.onTool) this.handlers.onTool(msg);
        break;
      case "settled":
        if (this.handlers.onSettled) this.handlers.onSettled(msg);
        break;
      case "error":
        if (this.handlers.onError) this.handlers.onError(msg);
        break;
      default:
        break;
    }
  }

  send(obj) {
    if (this.ws && this.ws.readyState === WebSocket.OPEN) {
      this.ws.send(JSON.stringify(obj));
      return true;
    }
    return false;
  }

  ask(captureId, tree, prompt, messages) {
    return this.send({ type: "ask", captureId, tree, messages: messages || [], prompt });
  }

  followUp(captureId, prompt) {
    return this.send({ type: "follow_up", captureId, prompt });
  }

  abort(captureId) {
    if (this.ws && this.ws.readyState === WebSocket.OPEN) {
      this.ws.send(JSON.stringify({ type: "abort", captureId }));
    }
  }

  close() {
    this.manualClose = true;
    if (this.reconnectTimer) clearTimeout(this.reconnectTimer);
    if (this.ws) this.ws.close();
    this.ws = null;
  }
}

// Expose for the side panel (classic script scope).
if (typeof window !== "undefined") {
  window.AgentClient = AgentClient;
}

// Persistence of agent conversations as pi-native session evidence (Decision 04).
//
// One artefact = one capture tree line with an `agent` envelope, and the full
// conversation written verbatim to `data/sessions/<uuid>/session.jsonl` in pi's
// native v3 session format — the same format the factory knowledge base stores
// and `extract-context` understands. Answers are saved verbatim, never edited.

import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";

export function newSessionId() {
  return crypto.randomUUID();
}

export function newEntryId() {
  return crypto.randomBytes(4).toString("hex");
}

// Sum the reported cost across assistant messages (usage.cost.total). Returns 0
// when usage data is absent (e.g. a stubbed run).
export function costOfMessages(messages) {
  let total = 0;
  for (const msg of messages || []) {
    const cost = msg && msg.usage && msg.usage.cost;
    if (cost && typeof cost.total === "number") total += cost.total;
  }
  return total;
}

export function currentModelOf(messages, fallback) {
  for (const msg of messages || []) {
    if (msg && msg.role === "assistant" && msg.model) return msg.model;
  }
  return fallback || "";
}

// Serialize a list of AgentMessages into a pi-native v3 session.jsonl string.
// First line is the session header; each subsequent line is a `message` entry
// linked by id/parentId into a linear tree (the path pi walks to rebuild the
// context window).
export function serializeSession(messages, { sessionId, cwd }) {
  const header = {
    type: "session",
    version: 3,
    id: sessionId,
    timestamp: new Date().toISOString(),
    cwd: cwd || process.cwd(),
  };
  const lines = [JSON.stringify(header)];
  let parentId = null;
  for (const msg of messages || []) {
    const id = newEntryId();
    const timestamp = new Date(
      typeof msg.timestamp === "number" ? msg.timestamp : Date.now()
    ).toISOString();
    const entry = { type: "message", id, parentId, timestamp, message: msg };
    lines.push(JSON.stringify(entry));
    parentId = id;
  }
  return lines.join("\n") + "\n";
}

// Persist messages to data/sessions/<sessionId>/session.jsonl. Returns the
// envelope fragments the capture server accepts.
export function persistSession(dataDir, sessionId, messages) {
  const dir = path.join(dataDir, "sessions", sessionId);
  fs.mkdirSync(dir, { recursive: true });
  const file = path.join(dir, "session.jsonl");
  fs.writeFileSync(file, serializeSession(messages, { sessionId }), "utf8");
  return {
    sessionId,
    sessionFile: path.join("sessions", sessionId, "session.jsonl").split(path.sep).join("/"),
  };
}

// Model stack for the capture agent service (Decision 02).
//
// Inference runs through OpenRouter via pi's ModelRuntime. The API key lives
// ONLY in this service's environment (OPENROUTER_API_KEY) — never in the
// browser. Default model deepseek/deepseek-v4-flash (thinking on), overridable
// with AGENT_MODEL.
//
// Auth + registry are in-memory: nothing sensitive is ever written to disk on
// the host, and the repo stays free of stray credential/registry files. The
// openrouter model is resolved from pi's built-in model registry.

import { AuthStorage, ModelRegistry } from "@earendil-works/pi-coding-agent";

export const DEFAULT_MODEL = "deepseek/deepseek-v4-flash";

// Design note on temperature: pi's session API does not expose a per-session
// temperature knob to SDK callers for reasoning models (temperature lives on
// provider StreamOptions that pi controls internally). The PRD's "~0.2" is
// honoured as documented intent; pi manages temperature for reasoning models
// itself. See outbox decisions.

export function createModelStack() {
  const authStorage = AuthStorage.inMemory();
  if (process.env.OPENROUTER_API_KEY) {
    authStorage.setRuntimeApiKey("openrouter", process.env.OPENROUTER_API_KEY);
  }
  const modelRegistry = ModelRegistry.inMemory(authStorage);
  return { authStorage, modelRegistry };
}

export function resolveModel(modelRegistry) {
  const id = process.env.AGENT_MODEL || DEFAULT_MODEL;
  const model = modelRegistry.find("openrouter", id);
  if (!model) {
    throw new Error(`Model not found on provider "openrouter": ${id}`);
  }
  return model;
}

