function addAgentBubble(cls, text) {
  const div = document.createElement("div");
  div.className = "agent-msg " + cls;
  div.textContent = text || "";
  agentThread.appendChild(div);
  return div;
}

// --- lightweight markdown rendering (HTML-escaped, then formatted) ---
function escapeHtml(s) {
  return String(s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}
function fmtInline(s) {
  return s
    .replace(/`([^`]+)`/g, "<code>$1</code>")
    .replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>")
    .replace(/(^|[^*])\*([^*\n]+)\*/g, "$1<em>$2</em>")
    .replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, '<a href="$2" target="_blank" rel="noopener">$1</a>');
}
// Turn escaped text into HTML blocks (paragraphs / lists / headings / code).
function renderMarkdown(text) {
  const esc = escapeHtml(text);
  const out = [];
  let listType = null; // 'ul' | 'ol' | null
  let inCode = false;
  const closeList = () => { if (listType) { out.push("</" + listType + ">"); listType = null; } };
  for (const raw of esc.split("\n")) {
    const t = raw.trim();
    if (inCode) {
      if (t.startsWith("```")) { out.push("</pre>"); inCode = false; }
      else out.push(t);
      continue;
    }
    if (t.startsWith("```")) { closeList(); out.push("<pre class='md-code'>"); inCode = true; continue; }
    if (t === "") { closeList(); continue; }
    const h = t.match(/^(#{1,4})\s+(.*)$/);
    if (h) { closeList(); out.push("<h" + h[1].length + ">" + fmtInline(h[2]) + "</h" + h[1].length + ">"); continue; }
    const ul = t.match(/^[-•*]\s+(.*)$/);
    const ol = t.match(/^\d+[.)]\s+(.*)$/);
    if (ul) {
      if (listType !== "ul") { closeList(); out.push("<ul>"); listType = "ul"; }
      out.push("<li>" + fmtInline(ul[1]) + "</li>");
    } else if (ol) {
      if (listType !== "ol") { closeList(); out.push("<ol>"); listType = "ol"; }
      out.push("<li>" + fmtInline(ol[1]) + "</li>");
    } else {
      closeList(); out.push("<p>" + fmtInline(t) + "</p>");
    }
  }
  if (inCode) out.push("</pre>");
  closeList();
  return out.join("\n");
}

