_onEvent(event) {
  if (event.type === "message_update" && event.assistantMessageEvent) {
    const sub = event.assistantMessageEvent;
    if (sub.type === "text_delta" && this.handlers.onDelta) {
      this.handlers.onDelta(sub.delta);
    } else if (sub.type === "thinking_delta" && this.handlers.onThinking) {
      // Reasoning trace token — streamed so the UI can show the model's thinking.
      this.handlers.onThinking(sub.delta);
    }
  } else if (event.type === "tool_execution_start") {
    if (this.handlers.onTool) {
      this.handlers.onTool({ tool: event.toolName, arg: event.args && event.args.url });
    }
  } else if (event.type === "agent_end") {
    if (this.handlers.onSettled) this.handlers.onSettled(event.messages || []);
  } else if (event.type === "message_end" && this.handlers.onMessageEnd) {
    // reserved
  }
}

